UPDATE fbs_board_attr_journey_v1
SET last_sequence_no = #{nextSequenceNo},
    last_event_digest = #{nextEventDigest},
    intent_family = #{intentFamily},
    head_version = head_version + 1,
    updated_at = CURRENT_TIMESTAMP(3)
WHERE same_binding_key = #{sameBindingKey}
  AND head_version = #{expectedHeadVersion}
  AND last_sequence_no = #{expectedLastSequenceNo}
